                      </span>
                      <span v-if="item.status !== 'published'" @click="publishProduct(item)">
                        <el-link :underline="false" type="primary">发 布</el-link>
                      </span>
                      <span v-if="item.status !== 'published'" @click="editProduct(item)">
                        <el-link :underline="false" type="success">编 辑</el-link>
                      </span>
