import { getMyProducts } from '@/api/user'
import {
  getProductCatalogs,
  deleteProduct,
  closeProduct,
  publishProduct,
  getShareUrl
} from '@/api/vr'

const defaultQuery = {
  type: '',
  status: '',
  catalog_id: '',
  date_span: '',
  keyword: '',
  page: 0,
  page_size: 20,
}
export default {
  name: 'VIPProductIndex',
  components: {
    VrHeader: () => import('../../layout/header.vue'),
  },
  data() {
    return {
      statusItems: [],
      catalogItems: [],
      typeItems: [],
      nowTab: 'all',
      loading: true,
      products: [],
      listQuery: Object.assign({}, defaultQuery),
    }
  },
  computed: {
    total() {
      return this.paginator ? this.paginator.total : 0
    },
    isSSOLogin() {
      return parseInt(this.$cache.get('sso_auth')) === 1
    }
  },
  mounted() {
    // setTimeout(() => {
    //   this.products = [
    //     {
    //       id: 1,
    //       src: 'https://cdn.x360.cn/234/media/img/88b1c9fa5523e177.jpg',
