    //     },
    //   ]
    //   this.loading = false
    // }, 1000)
    this.getAllItems()
    this.search()
  },

  methods: {
    handleSizeChange(val) {
      console.log(`每页 ${val} 条`)
    },
    handleCurrentChange(val) {
      console.log(`当前页: ${val}`)
    },
    jumpCreateProductPage() {
      // TODO: 未来会修改
      this.$router.push({
        path: '/',
      })
    },
    onTypeTabChange(val) {
      this.nowTab = val
      if (val === 'all') {
        this.listQuery.type = ''
      } else if (val === 'trash') {
        this.listQuery.status = 'drafted'
      } else {
        this.listQuery.type = val
      }
      this.search()
    },
    getStatusType(status) {
      if (status === 'published') {
        return 'success'
      }
      if (status === 'drafted') {
        return 'warning'
      }
      if (status === 'closed') {
        return 'danger'
      }
      return 'info'
    },
    getAllItems() {
      Promise.all([
        this.getStatusItems(),
        this.getTypeItems(),
        this.getCatalogItems(),
      ])
        .then(() => {})
        .catch((err) => {
          console.log('getAllItems error:', err)
        })
    },
    async getStatusItems() {
      this.statusItems = await getDictItems('vr_product_status')
    },
    async getTypeItems() {
      this.typeItems = await getDictItems('vr_product_type')
    },
    async getCatalogItems() {
      this.catalogItems = await getProductCatalogs()
    },
    search() {
      this.loading = true
      this.listQuery.page = defaultQuery.page
      this.listQuery.page_size = defaultQuery.page_size
      this.getTableList()
    },
    resetSearch(clearSearchWhere = true) {
      if (clearSearchWhere) {
        this.listQuery = Object.assign({}, defaultQuery)
      }
      this.$refs.searchForm.resetFields()
      this.getTableList()
    },
    async getTableList(enableShowLoading = false) {
      if (enableShowLoading) {
        this.loading = true
      }
      const { list, paginator } = await getMyProducts(this.listQuery)
      if (!list.length && this.paginator.currentPage !== 1) {
        this.$set(this.listQuery, 'page', this.paginator.currentPage - 1)
        this.getTableList()
        return
      }

      this.products = list
      this.paginator = paginator
      setTimeout(() => {
        this.loading = false
      }, 1000)
    },
    showProductData(product) {
      this.$message.warning(`《${product.title}》作品数据暂未开放`)
    },
    deleteProduct(product) {
      this.$confirm(`删除不可恢复,确认要删除作品《${product.title}》?`, '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
      })
        .then(() => {
          deleteProduct(product.id).then(() => {
            this.getTableList(true)
          })
        })
        .catch(() => {})
    },
    closeProduct(product) {
      this.$confirm(`确认要关闭作品《${product.title}》?`, '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
      })
        .then(() => {
          closeProduct(product.id).then(() => {
            this.getTableList(true)
          })
        })
        .catch(() => {})
    },
    publishProduct(product) {
      this.$confirm(`确认发布作品《${product.title}》?`, '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
      }).then(() => {
        publishProduct(product.id).then(() => {
          this.getTableList(true)
        })
      })
    },
    showProduct(product) {
      // this.$router.push(`/view/${product.code}`)
      const routeData = this.$router.resolve({ path: `/view/${product.code}` })
      window.open(routeData.href, '_blank')
    },
    editProduct(product) {
      this.$router.push(`/diy/${product.id}`)
    },
    async shareProduct(product) {
      const res = await getShareUrl(product.id)
      if (res.url) {
        this.copyToClipboard(res.url)
      }
    },
    copyToClipboard(inputValue) {
      // 创建一个新的 textarea 元素，设置其值为 el-input 的值
      const textarea = document.createElement('textarea')
      textarea.value = inputValue
      // 将 textarea 添加到 DOM 中
      document.body.appendChild(textarea)
      // 选择并复制 textarea 的值
      textarea.select()
      document.execCommand('copy')
      // 移除 textarea 元素
      document.body.removeChild(textarea)
      // 提示复制成功
      this.$message.success('复制成功,赶紧去分享吧!')
    }
  },
}
</script>

